import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

describe('onError rejection cause', () => {
  it('preserves a non-Error rejection as the hook error cause [specs/hal-engine-config-hooks/spec.md#8]', async () => {
    const reason = {code: 503};
    const provider: AIProvider = {
      // eslint-disable-next-line require-yield
      async *sendMessage(): AsyncGenerator<MessageChunk> {
        throw reason;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const session: ChatSession = {sessionId: 'test', userId: 'user', entries: []};
    let observed: Error | undefined;
    const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'test'}), undefined, {
      hooks: {onError: async (_session, error) => { observed = error; }},
    });
    const rejection: unknown = await orchestrator.processMessage(session).catch((error: unknown) => error);
    expect({isError: observed instanceof Error, cause: observed?.cause, rejection}).toEqual({
      isError: true,
      cause: reason,
      rejection: reason,
    });
  });
});
EOF
 timeout 300 node --experimental-vm-modules node_modules/jest/bin/jest.js src/orchestration/onErrorCause.test.ts --runInBand"
